/**
 * TILAWA Tajweed Learning System
 * Comprehensive Tajweed rules with examples and visual guides
 */

export type TajweedCategory =
  | 'noon-tanwin'
  | 'meem'
  | 'lam'
  | 'madd'
  | 'hamza'
  | 'characteristics'
  | 'stops'

export type Difficulty = 'beginner' | 'intermediate' | 'advanced'

export interface TajweedExample {
  ayah: string
  surah: string
  surahNumber: number
  ayahNumber: number
  arabicText: string
  transliteration: string
  explanation: string
  audioUrl?: string
  imageUrl?: string
}

export interface TajweedRule {
  id: string
  name: string
  nameArabic: string
  category: TajweedCategory
  description: string
  descriptionArabic: string
  difficulty: Difficulty
  
  // Rule details
  rules: string[]
  exceptions: string[]
  
  // Examples
  examples: TajweedExample[]
  
  // Learning
  visualGuide: string
  mnemonicDevice?: string
  commonMistakes: string[]
  
  // Metadata
  createdAt: Date
  order: number
}

