/**
 * Get all tajweed rules
 */
export function getAllTajweedRules(): TajweedRule[] {
  return TAJWEED_RULES.sort((a, b) => a.order - b.order)
}

/**
 * Get rules by category
 */
export function getRulesByCategory(category: TajweedCategory): TajweedRule[] {
  return TAJWEED_RULES.filter((rule) => rule.category === category).sort(
    (a, b) => a.order - b.order
  )
}

/**
 * Get rules by difficulty
 */
export function getRulesByDifficulty(difficulty: Difficulty): TajweedRule[] {
  return TAJWEED_RULES.filter((rule) => rule.difficulty === difficulty).sort(
    (a, b) => a.order - b.order
  )
}

/**
 * Get single rule by ID
 */
export function getTajweedRule(id: string): TajweedRule | undefined {
  return TAJWEED_RULES.find((rule) => rule.id === id)
}

